package steps

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

//truebdd:concept when "operation"
func concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba(state *State, args []string) error {
	exact, operation, number := args[0], args[1], args[2]

	var command string
	switch operation {
	case "halves":
		command = "halve"
	case "doubles":
		command = "double"
	default:
		return fmt.Errorf("the step names no declared operation: %q", operation)
	}

	runArgs := []string{"run", "./services/calc", command}
	if exact != "" {
		if command != "halve" {
			return fmt.Errorf("the interface declares --exact for halve only, not for %s", command)
		}
		runArgs = append(runArgs, "--exact")
	}
	runArgs = append(runArgs, number)

	root, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("find the host root: %w", err)
	}
	for {
		if _, statErr := os.Stat(filepath.Join(root, "go.mod")); statErr == nil {
			break
		}
		parent := filepath.Dir(root)
		if parent == root {
			return fmt.Errorf("find the host root: no go.mod at or above the suite's working directory")
		}
		root = parent
	}

	cmd := exec.Command("go", runArgs...)
	cmd.Dir = root
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if runErr := cmd.Run(); runErr != nil {
		return fmt.Errorf("go %s: %w: %s", strings.Join(runArgs, " "), runErr, strings.TrimSpace(stderr.String()))
	}

	state.Output = strings.TrimRight(stdout.String(), "\n")
	return nil
}

package steps

import (
	"fmt"
	"regexp"
)

//truebdd:concept then "output"
func concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e(state *State, args []string) error {
	comparison, pattern := args[0], args[1]

	const (
		matches      = "matches"
		doesNotMatch = "does not match"
	)

	expression, err := regexp.Compile(pattern)
	if err != nil {
		return fmt.Errorf("the step's pattern is no regular expression: %q: %w", pattern, err)
	}

	found := expression.MatchString(state.Output)

	switch comparison {
	case matches:
		if !found {
			return fmt.Errorf("the calculator printed %q, which the pattern %q has no match in", state.Output, pattern)
		}
	case doesNotMatch:
		if found {
			return fmt.Errorf("the calculator printed %q, which the pattern %q has a match in", state.Output, pattern)
		}
	default:
		return fmt.Errorf("the step names no declared comparison: %q", comparison)
	}

	return nil
}

package steps

func Register(suite Registrar) {

	suite.Step("^the Owner (?:(exactly) )?(halves|doubles) (-?\\d+)$", concept40523ceb26a25e37e78222ac562623f48c38b52711218d94fe5cadea337eebba)

	suite.Step("^the calculator's output (matches|does not match) (.+)$", concept95123e5878d35715c67b1f901cd0d6e1fcafc896021616abdece460efff6ed7e)
}
